Certainly! Below is a simple C++ program using Qt5 that prompts the user to select a file directory, converts all Microsoft Excel files in that directory into CSV files, and places them in a new folder within the selected directory.

To achieve this, you will need to install the `Qt5` library and a library to handle Excel files, such as `libxlsxwriter`.

Here is the code:

```cpp
#include <QApplication>
#include <QFileDialog>
#include <QDir>
#include <QMessageBox>
#include <QDebug>
#include <QString>
#include <QFile>
#include <QTextStream>
#include <xlsxwriter.h>

void convertExcelToCsv(const QString &excelFilePath, const QString &csvFilePath) {
    lxw_workbook *workbook = workbook_new(excelFilePath.toStdString().c_str());
    if (!workbook) {
        qWarning() << "Failed to open workbook:" << excelFilePath;
        return;
    }

    lxw_worksheet *worksheet = workbook_get_worksheet_by_index(workbook, 0);
    if (!worksheet) {
        qWarning() << "Failed to get worksheet:" << excelFilePath;
        workbook_free(workbook);
        return;
    }

    QFile csvFile(csvFilePath);
    if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
        qWarning() << "Failed to open CSV file:" << csvFilePath;
        workbook_free(workbook);
        return;
    }

    QTextStream out(&csvFile);
    lxw_row_t row;
    lxw_col_t col;
    lxw_cell *cell;

    for (row = 0; row < worksheet_dim_rowmax(worksheet); ++row) {
        for (col = 0; col < worksheet_dim_colmax(worksheet); ++col) {
            cell = lxw_worksheet_cell(worksheet, row, col);
            if (cell) {
                out << QString::fromStdString(lxw_cell_string(cell));
            }
            if (col < worksheet_dim_colmax(worksheet) - 1) {
                out << ",";
            }
        }
        out << "\n";
    }

    csvFile.close();
    workbook_free(workbook);
}

void processDirectory(const QString &directoryPath) {
    QDir directory(directoryPath);
    if (!directory.exists()) {
        qWarning() << "Directory does not exist:" << directoryPath;
        return;
    }

    QStringList filters;
    filters << "*.xlsx";
    directory.setNameFilters(filters);

    QStringList excelFiles = directory.entryList(filters, QDir::Files);
    if (excelFiles.isEmpty()) {
        QMessageBox::information(nullptr, "Information", "No Excel files found in the selected directory.");
        return;
    }

    QString outputDirPath = directoryPath + QDir::separator() + "ConvertedCSVs";
    QDir outputDir(outputDirPath);
    if (!outputDir.exists()) {
        outputDir.mkpath(outputDirPath);
    }

    foreach (const QString &excelFile, excelFiles) {
        QString excelFilePath = directoryPath + QDir::separator() + excelFile;
        QString csvFilePath = outputDirPath + QDir::separator() + excelFile.replace(".xlsx", ".csv");
        convertExcelToCsv(excelFilePath, csvFilePath);
    }

    QMessageBox::information(nullptr, "Information", "Conversion completed successfully.");
}

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    QString directoryPath = QFileDialog::getExistingDirectory(nullptr, "Select Directory", QDir::homePath());
    if (directoryPath.isEmpty()) {
        return 0;
    }

    processDirectory(directoryPath);

    return app.exec();
}
```

### Explanation:
1. **Libraries and Includes**: The code includes necessary Qt5 and `libxlsxwriter` headers.
2. **convertExcelToCsv Function**: This function converts an Excel file to a CSV file.
3. **processDirectory Function**: This function processes the selected directory, finds all Excel files, and converts them to CSV files.
4. **main Function**: This function initializes the Qt application, prompts the user to select a directory, and processes the selected directory.

### Dependencies:
- **Qt5**: Ensure you have Qt5 installed and properly configured.
- **libxlsxwriter**: Install `libxlsxwriter` to handle Excel files. You can install it using your package manager or download it from the official website.

### Building the Project:
To build this project, you need to create a `.pro` file for Qt:

```pro
QT += core gui widgets
CONFIG += console
CONFIG -= app_bundle

SOURCES += main.cpp

INCLUDEPATH += /path/to/libxlsxwriter/include
LIBS += -L/path/to/libxlsxwriter/lib -lxlsxwriter
```

Replace `/path/to/libxlsxwriter` with the actual path to the `libxlsxwriter` library on your system.

### Running the Program:
1. Open a terminal.
2. Navigate to the directory containing your `.pro` file.
3. Run `qmake` to generate the Makefile.
4. Run `make` to build the project.
5. Run the generated executable.

This program will prompt the user to select a directory, convert all Excel files in that directory to CSV files, and place them in a new folder within the selected directory.

